var targetName=typeof(ForgeBattlefieldController).GetMethod("RedesignTargetName",flags);var targetSeat=typeof(ForgeBattlefieldController).GetMethod("RedesignTargetSeat",flags);var serviceField=typeof(ForgeBattlefieldController).GetField("service",flags);var savedService=serviceField.GetValue(ui);var service=OnlineMatchService.EnsureInstance();if(service.IsOnline||service.IsInMatch)return "No live service may be changed by this display adapter";
var lobbyProperty=typeof(OnlineMatchService).GetProperty("LobbyState");var savedLobby=lobbyProperty.GetValue(service);var seatProperty=typeof(OnlineMatchService).GetProperty("LocalSeat");var savedSeat=seatProperty.GetValue(service);
string ownName="长昵称测试玩家甲乙丙丁戊己庚辛壬癸子丑寅卯辰巳午";string otherName="对手长昵称测试ABCDEFGHIJKLMNOPQ";
