void Unbind(){serviceField.SetValue(ui,savedService);lobbyProperty.SetValue(service,savedLobby);seatProperty.SetValue(service,savedSeat);}
void Quiet(){foreach(var pointer in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){pointer.ResetHover();pointer.AllowHandHover=false;}typeof(ForgeBattlefieldController).GetMethod("LeaveInspectCard",flags).Invoke(ui,null);}
System.Collections.IEnumerator Present(ForgeSeatView v){Unbind();ui.Present(null,1,false,null,null,"");yield return null;Bind();ui.Present(v,1,false,null,null,"本地布局样例");Unbind();Quiet();yield return Wait(.12f);}
System.Collections.IEnumerator Run(){
 Check(ownName.Length<=24&&otherName.Length<=24,"sample nicknames respect player-name limit");
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){
  Resize(size.x,size.y);yield return Wait(.15f);
  foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){
   GamePreferences.SetLanguage(language);yield return null;while(!GamePreferences.Ready)yield return null;
   foreach(float scale in new[]{.85f,1f,1.3f}){
    GamePreferences.SetScale(scale);var v=Read(W+"stack-target-multi-ability-input.json");yield return Present(v);string context=size+"/"+language+"/"+scale;var row=Root().Find("StackColumn/Viewport/Content/StackEntry_0");var label=row.Find("CompactTargets").GetComponent<UnityEngine.UI.Text>();string value=label.text;
    Check(value.Contains("<color="+Color(1)+">")&&value.Contains("<color="+Color(2)+">"),context+" mixed own and opponent targets color independently of source");Check(value.Count(c=>c=='↳')==3,context+" three targets retained");Check(label.supportRichText&&label.GetComponent<PreferenceText>().Literal,context+" target markup renders literally without nickname retranslation");Check(label.preferredHeight<=label.rectTransform.rect.height+2,context+" multi-target text fits its measured rectangle");
    var effect=row.Find("CompactEffect/Content/CompactNote").GetComponent<UnityEngine.UI.Text>();Check(!effect.text.Contains("+1/+0"),context+" trigger body excludes source's other activated ability");Check(row.Find("CompactOwner").GetComponent<UnityEngine.UI.Text>().text.StartsWith(ownName+" · "),context+" longest player label preserves exact name");
   }
   Save("RUNNING");
  }
 }
 GamePreferences.SetLanguage("en-US");yield return null;while(!GamePreferences.Ready)yield return null;GamePreferences.SetScale(1);var current=Read(W+"stack-target-multi-ability-input.json");yield return Present(current);Bind();
 var t=current.stackItems[0].targets[0];Check(Seat(t)==1,"ordinary own battlefield target uses current controller");current.players[0].battlefield=Array.FindAll(current.players[0].battlefield,c=>c.id!=t.id);current.players[1].battlefield=current.players[1].battlefield.Append(t.card).ToArray();Check(Seat(t)==2&&Target(t).Contains(Color(2)),"stolen permanent uses public current controller despite owner being self");t.leftZone=true;Check(Seat(t)==1,"left-zone target does not bind new same-ID incarnation");
 t=new ForgeStackTarget{kind="card",zone="Graveyard",ownerSeat=1,card=new ForgeCardView{name="Same card"}};Check(Seat(t)==1&&Target(t).Contains(Color(1)),"graveyard target uses owner");t.zone="Exile";t.ownerSeat=2;Check(Target(t).Contains(Color(2)),"exile target uses owner");t.ownerSeat=0;t.card.ownerSeat=0;Check(!Target(t).Contains("<color="),"unknown identity remains neutral");t.card.faceDown=true;t.card.name="SECRET_CARD_NAME";Check(!Target(t).Contains("SECRET"),"concealed target keeps generic public name");
 var baseView=Sample();ui.Present(baseView,1,false,null,null,"");var st=baseView.stackItems[0].targets[0];Check(Seat(st)==1&&Target(st).Contains("Stack 2")&&Target(st).Contains(Color(1)),"stack target keeps accurate stack ID/position and target controller");st.ownerSeat=2;Check(Seat(st)==1,"stack controller takes precedence over source card owner");st.leftZone=true;Check(Seat(st)==2&&Target(st).Contains("left the stack"),"departed stack target keeps old owner fallback and departure status");
 mock.players[0].displayName="You";t=new ForgeStackTarget{kind="player",playerSeat=1};Check(Target(t).Contains(">You</color>"),"explicit player target colors a role-like real nickname");mock.players[0].displayName=ownName;
 seatProperty.SetValue(service,3);Check(!Target(t).Contains("<color="),"spectator does not invent own/enemy target colors");Unbind();
 // Actual screenshots: complete bodies, target color distinctions, long names.
 Resize(1920,1080);GamePreferences.SetLanguage("zh-CN");GamePreferences.SetScale(1);yield return null;while(!GamePreferences.Ready)yield return null;
 foreach(var shot in new[]{new[]{"stack-target-two-abilities-input.json","stack-target-abilities-long-names.png"},new[]{"native-full-seat.json","stack-target-spells-long-names.png"}}){
  var v=Read(W+shot[0]);yield return Present(v);typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",flags).Invoke(ui,new object[]{true});Quiet();yield return Wait(.4f);ScreenCapture.CaptureScreenshot(W+shot[1]);yield return new WaitForEndOfFrame();
 }
 Unbind();Restore();yield return null;while(!GamePreferences.Ready)yield return null;yield return Present(Sample());Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int i=0;i<100000;i++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});Unbind();Restore();Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Target-color UI validation and actual screenshots started";
